//! 📜️ Store report replay obtains genuine snapshot and ledger operation projections before semantic birth.
use super::*;
use semio_framework_value::{RetirementDemand,ValueRefusalKind,retained_clone::retained_clone_grant_admits};
impl<P,M> ArtifactStore<P,M>where P:ToValue+ArtifactPack+Send+Sync+'static,M:ToValue+Mutation<P>+OpBinary+OpText+Send+'static{
 pub(crate) fn step_original_report_replay(&mut self,owner:&mut ArtifactDerivedReplay<P,M>,grant:RetainedCloneGrant,control:&mut semio_framework_value::NativeDecodeControl<'_>,deadline:&mut dyn FnMut()->bool)->Result<ReplayStep,VcsError>{
  let progress=owner.replay.as_ref().ok_or(VcsError::HistoryReplaying)?.progress();if deadline()||grant.maximum_items==0{return Ok(ReplayStep::Pending(progress));}owner.preparation_receipt=Default::default();
  if let Some(failed)=owner.failed_operation.as_mut(){owner.preparation_receipt=failed.close_step(grant).map_err(VcsError::InverseRefused)?.progress();if failed.terminal_is_empty(){owner.failed_operation=None;}return Ok(ReplayStep::Pending(progress));}
  let replay=owner.replay.as_mut().unwrap();
  if owner.history_source.is_some()&&(replay.finished||owner.history_operation.is_some_and(|(cursor,_)|cursor!=replay.cursor)){let source=owner.history_source.as_mut().unwrap();source.begin_close();owner.preparation_receipt=source.close_step(&mut self.log.envelope.vcs.edits,grant).map_err(VcsError::InverseRefused)?.progress();if source.terminal_is_empty(){owner.history_source=None;owner.history_operation=None;}return Ok(ReplayStep::Pending(progress));}
  if owner.history_source.is_some(){owner.history_operation=Some((replay.cursor,replay.operation));}
  if replay.finished{
   if let Some(factory)=owner.history_issuer_close.as_mut(){owner.preparation_receipt=factory.step(grant).map_err(VcsError::InverseRefused)?.progress();if factory.terminal_is_empty(){owner.history_issuer_close=None;}return Ok(ReplayStep::Pending(progress));}
   if owner.history_issuer.is_some(){let d=RetirementDemand{copy_bytes:size_of::<Arc<dyn ArtifactOwnedValueRetirementFactory<Edit<M>>>>(),depth:1,..Default::default()};if !retained_clone_grant_admits(grant,d){return Ok(ReplayStep::Pending(progress));}owner.history_issuer_close=Some(semio_framework_value::FactoryAuthority::new(owner.history_issuer.take().unwrap()));owner.preparation_receipt=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};return Ok(ReplayStep::Pending(progress));}return Ok(ReplayStep::Finished(progress));
  }
  let ready=replay.operation_preparation.is_none()&&replay.prepared_operation.is_none()&&replay.operation_retirement.is_none()&&replay.operation_message_settlement.is_none()&&replay.replay_retirement.is_none()&&replay.prefix_message_retirement.is_none();
  if ready&&replay.cursor<replay.order.len()&&replay.operation<self.applied_edit(replay.cursor)?.forwards.len(){
   if owner.history_issuer.is_none(){owner.preparation_receipt=self.admit_history_edit_read_issuer(&mut owner.history_issuer,grant).map_err(VcsError::InverseRefused)?.progress();return Ok(ReplayStep::Pending(progress));}
   if owner.history_source.is_none(){let slot=self.applied_revision().applied.get(replay.cursor).and_then(|record|record.ledger_key).ok_or(VcsError::HistoryReplaying)?;let key=self.log.envelope.vcs.edits.retained_read_key(slot).ok_or(VcsError::HistoryReplaying)?;if let Some((source,p))=super::OriginalHistorySource::admit(key,self.log.envelope.vcs.edits.retained_read_issuer(key).map_err(VcsError::InverseRefused)?.unwrap_or(owner.history_issuer.as_ref().unwrap()),grant).map_err(VcsError::InverseRefused)?{owner.history_source=Some(source);owner.history_operation=Some((replay.cursor,replay.operation));owner.preparation_receipt=p;}return Ok(ReplayStep::Pending(progress));}
   if owner.history_input.is_none(){let index=replay.operation;owner.preparation_receipt=owner.history_source.as_mut().unwrap().advance(&mut self.log.envelope.vcs.edits,&mut owner.history_input,index+1,|edit|&edit.forwards[index],grant).map_err(VcsError::InverseRefused)?.progress();return Ok(ReplayStep::Pending(progress));}
   if !replay.drafts.is_empty()||!replay.supersessions.is_empty(){return Err(VcsError::InverseRefused(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original report replacement requires its retained semantic input issuer")));}
   let parent=SnapshotRead::<P>::capture_copy_byte_demand()+2*size_of::<Arc<dyn semio_framework_value::FactoryRetirement>>()+size_of::<ArtifactDerivedOperation<P,M>>();let mut demand=replay.original_preparation_birth_demand().map_err(VcsError::InverseRefused)?;demand.copy_bytes=demand.copy_bytes.checked_add(parent).ok_or(VcsError::HistoryReplaying)?;if !retained_clone_grant_admits(grant,demand){return Ok(ReplayStep::Pending(progress));}
   let base=replay.state.as_ref().ok_or(VcsError::HistoryReplaying)?;let alias=Arc::clone(base);let lease=match self.owners.snapshot_read_leases.try_issue(Arc::clone(&alias)){Ok(lease)=>lease,Err(alias)=>{drop(alias);return Ok(ReplayStep::Pending(progress));}};let context=ArtifactReplayPreparationContext{mode:if replay.cursor<replay.prefix_until{ArtifactReplayPreparationMode::Prefix}else{ArtifactReplayPreparationMode::Report},operation_index:replay.operation as u32,generation:owner.generation,base_revision:owner.revision};let mut request=Some(ArtifactReplayPreparationRequest{base:SnapshotRead::new(alias,lease),input:owner.history_input.take().unwrap(),context,snapshots:Arc::clone(self.owners.initial_snapshot_retirement_factory.as_ref().ok_or(VcsError::HistoryReplaying)?),mutations:Arc::clone(self.owners.mutation_retirement_factory.as_ref().ok_or(VcsError::HistoryReplaying)?)});let child=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-parent,..grant};match replay.admit_original_preparation(&mut request,child){Ok(Some(mut p))=>{p.copied_bytes+=parent;owner.preparation_receipt=p;},Ok(None)=>{owner.failed_operation=Some(self.retain_refused_replay_request(request.take().unwrap()));owner.preparation_receipt=RetainedCloneProgress{copied_items:1,copied_bytes:parent,..Default::default()};},Err(error)=>{if let Some(request)=request.take(){owner.failed_operation=Some(self.retain_refused_replay_request(request));}let mut p=error.retained_progress();p.copied_bytes+=parent;owner.preparation_receipt=p;return Err(VcsError::InverseRefused(error.with_retained_progress(p)));}}return Ok(ReplayStep::Pending(progress));
  }
  let step=replay.step_granted(&IndexedAppliedReplayEdits{edits:&self.log.envelope.vcs.edits,revision:&self.cursor.revision_accumulator,ids:&self.log.applied_edit_ids},grant,control,deadline);owner.preparation_receipt=match &step{Err(VcsError::InverseRefused(error))=>error.retained_progress(),_=>std::mem::take(&mut replay.native_receipt)};let step=step?;Ok(if matches!(step,ReplayStep::Finished(_)){ReplayStep::Pending(replay.progress())}else{step})
 }
}
